import plantList from '../datas/plantList';
import PlantItem from './PlantItem';
import '../styles/ShoppingList.css';

function ShoppingList() {
  return (
    <section className="shopping-list" id="collection">
      <div className="collection-heading">
        <div>
          <span className="section-kicker">THE PLANT EDIT</span>
          <h2>Find your <span>green crush</span></h2>
        </div>
        <p className="collection-count">{plantList.length} little beauties ♡</p>
      </div>

      <div className="lmj-plant-list">
        {plantList.map(({ id, cover, name, water, light }) => (
          <PlantItem
            key={id}
            id={id}
            cover={cover}
            name={name}
            water={water}
            light={light}
          />
        ))}
      </div>
    </section>
  );
}

export default ShoppingList;
